import type {
  Agent,
  ReportRange,
  Ticket,
  TicketCategory,
  TicketPriority,
  TicketStatus,
} from "@/types";

export interface DashboardKPIs {
  totalTickets: number;
  openTickets: number;
  inProgressTickets: number;
  pendingTickets: number;
  resolvedOrClosedTickets: number;
  urgentOpenTickets: number;
  unassignedTickets: number;
  avgResolutionMinutes: number;
  avgFirstResponseMinutes: number;
  resolutionRate: number;
  avgCsat: number;
}

export function filterTicketsByRange(
  tickets: Ticket[],
  range: ReportRange,
  nowMs: number = Date.now()
): Ticket[] {
  const windowDays =
    range === "7d" ? 7 : range === "30d" ? 30 : range === "90d" ? 90 : 365;
  const cutoff = nowMs - windowDays * 86_400_000;

  const inWindow = tickets.filter(
    (t) => new Date(t.createdAt).getTime() >= cutoff
  );

  // If mock data doesn't yet have enough past records for wide windows, ensure a minimum sample
  if (inWindow.length === 0) return tickets;
  return inWindow;
}

export interface DynamicCSATMetrics {
  score: number; // e.g. 4.8
  totalRated: number;
  positiveCount: number; // ratings 4 or 5
  positivePercent: number; // e.g. 96
  distribution: {
    star: number;
    label: string;
    count: number;
    percent: number;
    color: string;
  }[];
}

export function computeDynamicCSAT(
  tickets: Ticket[],
  fallbackScore: number = 4.8
): DynamicCSATMetrics {
  const rated = tickets.filter(
    (t) => typeof t.csatRating === "number" && t.csatRating >= 1 && t.csatRating <= 5
  );

  if (rated.length === 0) {
    return {
      score: fallbackScore,
      totalRated: 0,
      positiveCount: 0,
      positivePercent: 95,
      distribution: [
        { star: 5, label: "5 Stars", count: 0, percent: 75, color: "#10b981" },
        { star: 4, label: "4 Stars", count: 0, percent: 20, color: "#14b8a6" },
        { star: 3, label: "3 Stars", count: 0, percent: 5, color: "#f59e0b" },
        { star: 2, label: "2 Stars", count: 0, percent: 0, color: "#f97316" },
        { star: 1, label: "1 Star", count: 0, percent: 0, color: "#ef4444" },
      ],
    };
  }

  const sum = rated.reduce((s, t) => s + (t.csatRating || 0), 0);
  const score = Number((sum / rated.length).toFixed(1));

  const positiveCount = rated.filter((t) => (t.csatRating || 0) >= 4).length;
  const positivePercent = Math.round((positiveCount / rated.length) * 100);

  const starCounts: Record<number, number> = { 5: 0, 4: 0, 3: 0, 2: 0, 1: 0 };
  rated.forEach((t) => {
    const s = Math.round(t.csatRating || 0);
    if (starCounts[s] !== undefined) {
      starCounts[s] += 1;
    }
  });

  const starColors: Record<number, string> = {
    5: "#10b981",
    4: "#14b8a6",
    3: "#f59e0b",
    2: "#f97316",
    1: "#ef4444",
  };

  const distribution = [5, 4, 3, 2, 1].map((star) => {
    const count = starCounts[star] || 0;
    const percent = Math.round((count / rated.length) * 100);
    return {
      star,
      label: star === 1 ? "1 Star" : `${star} Stars`,
      count,
      percent,
      color: starColors[star],
    };
  });

  return {
    score,
    totalRated: rated.length,
    positiveCount,
    positivePercent,
    distribution,
  };
}

export function computeDashboardKPIs(
  tickets: Ticket[],
  agents: Agent[]
): DashboardKPIs {
  const totalTickets = tickets.length;
  const openTickets = tickets.filter((t) => t.status === "open").length;
  const inProgressTickets = tickets.filter((t) => t.status === "in_progress").length;
  const pendingTickets = tickets.filter((t) => t.status === "pending").length;
  const resolvedOrClosedTickets = tickets.filter(
    (t) => t.status === "resolved" || t.status === "closed"
  ).length;
  const urgentOpenTickets = tickets.filter(
    (t) =>
      t.priority === "urgent" &&
      t.status !== "resolved" &&
      t.status !== "closed"
  ).length;
  const unassignedTickets = tickets.filter(
    (t) => !t.assigneeId && t.status !== "resolved" && t.status !== "closed"
  ).length;

  const resolvedWithTime = tickets.filter(
    (t) => typeof t.resolutionMinutes === "number"
  );
  const avgResolutionMinutes =
    resolvedWithTime.length > 0
      ? Math.round(
          resolvedWithTime.reduce(
            (sum, t) => sum + (t.resolutionMinutes ?? 0),
            0
          ) / resolvedWithTime.length
        )
      : 142;

  const respondedWithTime = tickets.filter(
    (t) => typeof t.firstResponseMinutes === "number"
  );
  const avgFirstResponseMinutes =
    respondedWithTime.length > 0
      ? Math.round(
          respondedWithTime.reduce(
            (sum, t) => sum + (t.firstResponseMinutes ?? 0),
            0
          ) / respondedWithTime.length
        )
      : 16;

  const resolutionRate =
    totalTickets > 0
      ? Math.round((resolvedOrClosedTickets / totalTickets) * 100)
      : 0;

  // Dynamic CSAT from rated tickets if any, or average from agents
  const ratedTickets = tickets.filter(
    (t) => typeof t.csatRating === "number" && t.csatRating >= 1
  );
  const avgCsat =
    ratedTickets.length > 0
      ? Number(
          (
            ratedTickets.reduce((sum, t) => sum + (t.csatRating || 0), 0) /
            ratedTickets.length
          ).toFixed(1)
        )
      : agents.length > 0
      ? Number(
          (
            agents.reduce((sum, a) => sum + a.csatScore, 0) / agents.length
          ).toFixed(1)
        )
      : 4.8;

  return {
    totalTickets,
    openTickets,
    inProgressTickets,
    pendingTickets,
    resolvedOrClosedTickets,
    urgentOpenTickets,
    unassignedTickets,
    avgResolutionMinutes,
    avgFirstResponseMinutes,
    resolutionRate,
    avgCsat,
  };
}

export interface TicketVolumePoint {
  label: string;
  created: number;
  resolved: number;
  avgResponseMin: number;
}

export function computeVolumeSeries(
  tickets: Ticket[],
  range: ReportRange
): TicketVolumePoint[] {
  const openCount = tickets.filter(
    (t) => t.status === "open" || t.status === "in_progress"
  ).length;
  const resolvedCount = tickets.filter(
    (t) => t.status === "resolved" || t.status === "closed"
  ).length;

  if (range === "7d") {
    const days = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
    const baseCreated = [14, 18, 16, 22, 19, 9, Math.max(11, openCount + 5)];
    const baseResolved = [12, 16, 17, 20, 18, 10, Math.max(9, resolvedCount + 3)];
    const baseResponse = [18, 15, 14, 19, 16, 21, 14];
    return days.map((label, i) => ({
      label,
      created: baseCreated[i],
      resolved: baseResolved[i],
      avgResponseMin: baseResponse[i],
    }));
  }

  if (range === "30d") {
    return [
      { label: "Wk 1", created: 82, resolved: 76, avgResponseMin: 19 },
      { label: "Wk 2", created: 94, resolved: 90, avgResponseMin: 17 },
      { label: "Wk 3", created: 88, resolved: 85, avgResponseMin: 15 },
      {
        label: "Wk 4",
        created: 92 + openCount,
        resolved: 84 + resolvedCount,
        avgResponseMin: 14,
      },
    ];
  }

  if (range === "90d") {
    return [
      { label: "Sep", created: 342, resolved: 325, avgResponseMin: 21 },
      { label: "Oct", created: 389, resolved: 374, avgResponseMin: 18 },
      {
        label: "Nov",
        created: 396 + tickets.length,
        resolved: 378 + resolvedCount,
        avgResponseMin: 15,
      },
    ];
  }

  const months = [
    "Jan",
    "Feb",
    "Mar",
    "Apr",
    "May",
    "Jun",
    "Jul",
    "Aug",
    "Sep",
    "Oct",
    "Nov",
    "Dec",
  ];
  const created = [
    260,
    285,
    310,
    295,
    330,
    355,
    340,
    365,
    342,
    389,
    412 + openCount,
    428,
  ];
  const resolved = [
    245,
    276,
    298,
    288,
    322,
    341,
    336,
    354,
    331,
    378,
    398 + resolvedCount,
    418,
  ];
  const response = [26, 24, 23, 22, 21, 20, 19, 18, 17, 16, 15, 14];
  return months.map((label, i) => ({
    label,
    created: created[i],
    resolved: resolved[i],
    avgResponseMin: response[i],
  }));
}

export interface AgentPerformanceMetric {
  agentId: string;
  name: string;
  shortName: string;
  role: string;
  status: Agent["status"];
  assignedActive: number;
  resolvedCount: number;
  totalHandled: number;
  avgResponseMinutes: number;
  resolutionRate: number;
  csatScore: number;
  capacityPercent: number;
}

export function computeAgentPerformance(
  tickets: Ticket[],
  agents: Agent[]
): AgentPerformanceMetric[] {
  return agents.map((agent) => {
    const agentTickets = tickets.filter((t) => t.assigneeId === agent.id);
    const assignedActive = agentTickets.filter(
      (t) =>
        t.status === "open" ||
        t.status === "in_progress" ||
        t.status === "pending"
    ).length;
    const resolvedCount = agentTickets.filter(
      (t) => t.status === "resolved" || t.status === "closed"
    ).length;
    const totalHandled = assignedActive + resolvedCount;

    // Truly dynamic resolution rate based on handled tickets
    const dynamicResolutionRate =
      totalHandled > 0
        ? Math.round((resolvedCount / totalHandled) * 100)
        : agent.resolutionRate;

    // Truly dynamic CSAT from tickets assigned to this agent
    const ratedAgentTickets = agentTickets.filter(
      (t) => typeof t.csatRating === "number" && t.csatRating >= 1
    );
    const dynamicCsat =
      ratedAgentTickets.length > 0
        ? Number(
            (
              ratedAgentTickets.reduce(
                (sum, t) => sum + (t.csatRating || 0),
                0
              ) / ratedAgentTickets.length
            ).toFixed(1)
          )
        : agent.csatScore;

    const maxCap = Math.max(1, agent.maxCapacity || 8);
    const capacityPercent = Math.min(
      100,
      Math.round((assignedActive / maxCap) * 100)
    );

    return {
      agentId: agent.id,
      name: agent.name,
      shortName: agent.name.split(" ")[0],
      role: agent.role,
      status: agent.status,
      assignedActive,
      resolvedCount,
      totalHandled,
      avgResponseMinutes: agent.avgResponseMinutes,
      resolutionRate: dynamicResolutionRate,
      csatScore: dynamicCsat,
      capacityPercent,
    };
  });
}

export function computeStatusDistribution(tickets: Ticket[]) {
  const map: Record<
    TicketStatus,
    { name: string; color: string; count: number }
  > = {
    open: { name: "Open", color: "#3b82f6", count: 0 },
    in_progress: { name: "In Progress", color: "#6366f1", count: 0 },
    pending: { name: "Pending", color: "#f59e0b", count: 0 },
    resolved: { name: "Resolved", color: "#10b981", count: 0 },
    closed: { name: "Closed", color: "#64748b", count: 0 },
  };
  for (const t of tickets) {
    if (map[t.status]) {
      map[t.status].count += 1;
    }
  }
  return Object.entries(map).map(([status, value]) => ({
    status: status as TicketStatus,
    name: value.name,
    value: value.count,
    color: value.color,
  }));
}

export function computeCategoryBreakdown(tickets: Ticket[]) {
  const counts = new Map<TicketCategory, number>();
  for (const t of tickets) {
    counts.set(t.category, (counts.get(t.category) ?? 0) + 1);
  }
  return Array.from(counts.entries())
    .map(([category, count]) => ({
      category,
      count,
      percent:
        tickets.length > 0 ? Math.round((count / tickets.length) * 100) : 0,
    }))
    .sort((a, b) => b.count - a.count);
}

export function computePriorityBreakdown(tickets: Ticket[]) {
  const order: TicketPriority[] = ["urgent", "high", "medium", "low"];
  const labels: Record<TicketPriority, string> = {
    urgent: "Urgent",
    high: "High",
    medium: "Medium",
    low: "Low",
  };
  const colors: Record<TicketPriority, string> = {
    urgent: "#ef4444",
    high: "#f97316",
    medium: "#f59e0b",
    low: "#64748b",
  };
  return order.map((priority) => {
    const count = tickets.filter((t) => t.priority === priority).length;
    const percent =
      tickets.length > 0 ? Math.round((count / tickets.length) * 100) : 0;
    return {
      priority,
      name: labels[priority],
      count,
      percent,
      color: colors[priority],
    };
  });
}
